CREATE OR REPLACE FUNCTION lr_serverless_aws_us_catalog.bricksurance_policy.fn_policy_snapshot(in_policy_number STRING COMMENT 'Policy number, e.g. POL-2026-000001.')
RETURNS STRING
COMMENT 'One-line snapshot of a policy - line, status, cover period, year, currency. Returns: lob | status | period | underwriting year | currency, or NULL when unknown.'
RETURN (SELECT max(concat(line_of_business_code, ' | ', policy_status_code, ' | ',
                   cast(inception_date AS STRING), ' to ', cast(expiry_date AS STRING),
                   ' | uwy ', cast(underwriting_year AS STRING), ' | ', currency_code))
 FROM lr_serverless_aws_us_catalog.bricksurance_policy.policy WHERE policy_number = in_policy_number);
